import{_ as e,a as o,o as a,a6 as s}from"./chunks/framework.CJDy2q7X.js";const g=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"outline":false,"apiType":"rest"},"headers":[],"relativePath":"api/rest-api/admin/dashboard/index.md","filePath":"api/rest-api/admin/dashboard/index.md","lastUpdated":1787290888000}'),d={name:"api/rest-api/admin/dashboard/index.md"};function r(n,t,i,c,h,l){return a(),o("div",null,t[0]||(t[0]=[s('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The Dashboard menu returns the aggregate figures that power the Bagisto admin <strong>Dashboard</strong> screen — sales, orders, customers, visitors, stock alerts, top products and top customers. It mirrors the admin <strong>Dashboard</strong> landing page.</p><h2 id="the-dashboard-is-seven-separate-calls" tabindex="-1">The dashboard is <strong>seven</strong> separate calls <a class="header-anchor" href="#the-dashboard-is-seven-separate-calls" aria-label="Permalink to &quot;The dashboard is **seven** separate calls&quot;">​</a></h2><p>This is the most important thing to understand about this menu.</p><p>The Dashboard you see in the panel is <strong>not one response</strong>. The page is assembled from <strong>seven independent requests</strong>, one per section, each selected with the <code>?type=</code> query parameter. A single call returns <strong>one section</strong> of the dashboard. To render the whole screen, call the endpoint once per <code>type</code> (or only for the sections you need).</p><p>The <code>statistics</code> payload <strong>changes shape per <code>type</code></strong> — sometimes an object, sometimes a flat array — so always branch on <code>type</code> when consuming it.</p><table tabindex="0"><thead><tr><th>Dashboard section (admin panel)</th><th><code>type</code></th><th><code>statistics</code> is</th></tr></thead><tbody><tr><td><strong>Overall Details</strong> cards</td><td><code>over-all</code> (default)</td><td>object</td></tr><tr><td><strong>Today&#39;s Details</strong> + today&#39;s order list</td><td><code>today</code></td><td>object</td></tr><tr><td><strong>Stock Threshold</strong> product list</td><td><code>stock-threshold-products</code></td><td>array</td></tr><tr><td><strong>Store Stats</strong> sales chart</td><td><code>total-sales</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Visitors</strong> chart</td><td><code>total-visitors</code></td><td>object (with <code>over_time</code> series)</td></tr><tr><td><strong>Top Selling Products</strong> list</td><td><code>top-selling-products</code></td><td>array</td></tr><tr><td><strong>Customer With Most Sales</strong> list</td><td><code>top-customers</code></td><td>array</td></tr></tbody></table><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p><code>start</code> / <code>end</code> (both <code>YYYY-MM-DD</code>) bound the figures and drive the <code>previous</code> baseline behind every <code>progress</code> percentage — the previous period is the same-length window immediately before <code>start</code>. <code>start</code> defaults to <strong>30 days ago</strong>, <code>end</code> to <strong>today</strong>. <code>channel</code> (a channel <strong>code</strong>) scopes the figures to a single storefront channel.</p><h2 id="endpoints-in-this-menu" tabindex="-1">Endpoints in this menu <a class="header-anchor" href="#endpoints-in-this-menu" aria-label="Permalink to &quot;Endpoints in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/dashboard/stats.html">Dashboard statistics</a></td><td><code>GET /api/admin/dashboard/stats</code></td></tr></tbody></table><p>The Dashboard is read-only — there are no write actions, mass-actions or exports on this menu. For deeper, dedicated sales / customer / product reports, see <a href="/api/rest-api/admin/reporting/">Reporting</a>.</p><p>All Dashboard endpoints require only an admin Bearer token (no permission gate) — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',13)]))}const m=e(d,[["render",r]]);export{g as __pageData,m as default};
